// Persona = the assigned driver. Synthetic demo stand-in for a real driver chat.
// The facts block is the only ground truth; "Check reply" below rejects replies that contradict it.
const c = $json;
const s = c.snapshot || {};
const driver = (s.assignments || []).find(a => a.status === 'IN_PROGRESS') || (s.assignments || [])[0] || {};
const t = (s.tracking_latest || []).slice(-1)[0] || {};
const facts = {
  now: s.snapshot_now,
  order: { ref: c.order_ref, status: s.order?.status },
  car: (s.vehicles || []).map(v => `${v.make} ${v.model}`).join(', '),
  route: { from: s.pickup?.city || s.pickup?.name, to: s.delivery?.city || s.delivery?.site },
  latest_tracking: t.observed_at ? { observed_at: t.observed_at, km_remaining: t.distance_remaining_km, progress: t.progress_fraction, eta: t.estimated_delivery_at, location_quality: t.location_quality } : 'none',
  delivery_windows: (s.time_windows || []).map(w => ({ purpose: w.purpose, start: w.start_at, end: w.end_at })),
  incidents: (s.incidents || []).map(i => ({ kind: i.kind, status: i.status, opened_at: i.opened_at, resolved_at: i.resolved_at })),
  alerts: (s.alerts || []).map(a => a.summary),
  expenses_so_far: (s.expenses || []).map(e => ({ kind: e.kind, amount_cents: e.amount_cents, currency: e.currency, status: e.status })),
  travel_bookings: (s.travel_reservations || []).map(r => ({ route: r.route_label, departs: r.departure_at, cutoff: r.check_in_cutoff_at, state: r.snapshot_journey_state })),
};
const chat = [
  ...(s.messages || []).filter(m => m.channel === 'driver_chat').map(m => `${m.author_type}: ${m.body}`),
  ...(c.case_timeline || []).filter(t => t.kind === 'driver_message').map(t => `${t.actor}: ${t.text}`),
];
const ask = $('Start').first().json.text;
const prompt = `You are ${driver.driver || 'the driver'}, a freelance car delivery driver for Bahn Express, driving order ${c.order_ref}.
FACTS (ground truth, never contradict, never change a number):
${JSON.stringify(facts, null, 1)}
Your earlier chat (stay consistent with what you already said):
${chat.join('\n') || '(none)'}

Operations just wrote to you:
"${ask}"

Rules:
- Times, distances, ETA, booking times and incident details come only from FACTS. Do not give other numbers.
- Location: say where you are only relative to FACTS, e.g. "on the way to ${facts.route.to}, about ${t.distance_remaining_km ?? 'some'} km left". You may mention a generic stop (rest area, petrol station) but never name a road, town or place that is not in FACTS.
- If FACTS do not cover what is asked, say you will check, or answer vaguely. Never invent a new problem, cost or delay.
- For a photo, say you sent it. You are not a mechanic and never diagnose.
Reply as the driver in 1-3 short sentences, plain chat style. Output only the reply text.`;
// Test switch from the control room ("driver does not answer"): logged as a test_flag line, expires after 20 min.
const flag = (c.case_timeline || []).filter((x) => x.kind === 'test_flag').slice(-1)[0];
const silent = !!flag && flag.text === 'driver_unreachable' && Date.now() - Date.parse(flag.at) < 20 * 60e3;
return [{ json: { prompt, facts, silent } }];

// ponytail: placeholder cut-off from the Settings page. Unclear or failed check falls back to a reply built only from facts.
const CUT = $('Get context').first().json.settings?.glide_fact_check ?? 0.5;
const { reply } = $('Check reply').first().json;
const a = $json.answers?.contradicts;
const p = a ? Number(a.noul) : null;
if (p !== null && p < CUT && reply) return [{ json: { reply, grounding: `checked (p_contradiction=${p.toFixed(2)})` } }];
const f = $('Driver prompt').first().json.facts;
const lt = f.latest_tracking;
const where = lt && lt !== 'none' && lt.km_remaining != null ? `On the way to ${f.route.to}, about ${lt.km_remaining} km left.` : `On the way to ${f.route.to}.`;
return [{ json: { reply: `${where} Let me check that and get back to you.`,
  grounding: !reply ? "fallback: model returned empty text" : p === null ? `fallback: check unavailable (${$json.error?.message || 'no answer'})` : `fallback: generated reply contradicted facts (p=${p.toFixed(2)}): ${reply}` } }];

// Ask GLiDE whether the generated reply contradicts the facts the driver was given.
const facts = $('Driver prompt').first().json.facts;
const reply = String($json.text || '').trim();
const glide_body = {
  model: 'fastino/GLiDE', store: false,
  state: { facts, driver_reply: reply },
  questions: { contradicts: {
    type: 'noul',
    instructions: 'Does driver_reply state anything that conflicts with facts: a different time, ETA, distance, booking, incident or problem; a payment, cost, repair, recovery or other event that is not in facts; or a named road/town/place that is not in facts?',
    criteria: { true: 'The reply conflicts with facts, or claims a place, payment or event not in facts', false: 'The reply is consistent with facts (generic stops and vague answers are fine)' },
  } },
};
return [{ json: { reply, glide_body } }];
